<?php $title='Login'; require __DIR__.'/../includes/header.php'; require __DIR__.'/../config/database.php';
$error=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $email=trim($_POST['email']??'');$password=$_POST['password']??''; $st=$pdo->prepare("SELECT * FROM users WHERE email=? LIMIT 1");$st->execute([$email]);$u=$st->fetch(); if($u&&password_verify($password,$u['password_hash'])&&$u['status']==='active'){session_regenerate_id(true);$_SESSION['user_id']=$u['id'];$_SESSION['role']=$u['role'];$_SESSION['name']=$u['name'];$dest=$u['role']==='admin'?'admin/dashboard.php':($u['role']==='provider'?'provider/dashboard.php':'customer/dashboard.php');redirect(BASE_URL.$dest);} $error='Invalid email, password, or account status.';} ?>
